import path from "path"
import react from "@vitejs/plugin-react"
import tailwindcss from "@tailwindcss/vite"
import { defineConfig } from "vite"

export default defineConfig({
  plugins: [react(), tailwindcss()],
  resolve: {
    alias: {
      "@": path.resolve(__dirname, "./src"),
    },
  },
  build: {
    rollupOptions: {
      input: {
        main: path.resolve(__dirname, "index.html"),
        learn: path.resolve(__dirname, "learn.html"),
        donate: path.resolve(__dirname, "donate.html"),
        tagAi: path.resolve(__dirname, "tag-ai.html"),
        tagScraping: path.resolve(__dirname, "tag-web-scraping.html"),
      },
    },
  },
})

@import "tailwindcss";

@theme {
  --color-border: hsl(var(--border));
  --color-input: hsl(var(--input));
  --color-ring: hsl(var(--ring));
  --color-background: hsl(var(--background));
  --color-foreground: hsl(var(--foreground));
  --color-primary: hsl(var(--primary));
  --color-primary-foreground: hsl(var(--primary-foreground));
  --color-secondary: hsl(var(--secondary));
  --color-secondary-foreground: hsl(var(--secondary-foreground));
  --color-destructive: hsl(var(--destructive));
  --color-destructive-foreground: hsl(var(--destructive-foreground));
  --color-muted: hsl(var(--muted));
  --color-muted-foreground: hsl(var(--muted-foreground));
  --color-accent: hsl(var(--accent));
  --color-accent-foreground: hsl(var(--accent-foreground));
  --color-popover: hsl(var(--popover));
  --color-popover-foreground: hsl(var(--popover-foreground));
  --color-card: hsl(var(--card));
  --color-card-foreground: hsl(var(--card-foreground));
  --radius-lg: var(--radius);
  --radius-md: calc(var(--radius) - 2px);
  --radius-sm: calc(var(--radius) - 4px);

  --font-sans: 'Plus Jakarta Sans', ui-sans-serif, system-ui, sans-serif;
  --font-display: 'Space Grotesk', ui-sans-serif, system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', ui-monospace, monospace;
}

@layer base {
  :root {
    --background: 0 0% 100%;
    --foreground: 228 71% 4%;
    --card: 0 0% 100%;
    --card-foreground: 228 71% 4%;
    --popover: 0 0% 100%;
    --popover-foreground: 228 71% 4%;
    --primary: 228 71% 9%;
    --primary-foreground: 0 0% 100%;
    --secondary: 40 33% 96%;
    --secondary-foreground: 228 71% 9%;
    --muted: 40 20% 96%;
    --muted-foreground: 220 9% 46%;
    --accent: 40 99% 60%;
    --accent-foreground: 228 71% 9%;
    --destructive: 0 84% 60%;
    --destructive-foreground: 0 0% 100%;
    --border: 40 20% 90%;
    --input: 40 20% 90%;
    --ring: 40 99% 60%;
    --radius: 0.5rem;
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground antialiased;
    font-family: var(--font-sans);
  }
  h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-display);
  }
}

/* Custom scrollbar */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: hsl(var(--muted-foreground) / 0.3);
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: hsl(var(--muted-foreground) / 0.5);
}

/* Animation utilities */
@keyframes fade-in-up {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-fade-in-up {
  animation: fade-in-up 0.4s ease-out both;
}

/* Grain texture overlay */
.grain::before {
  content: '';
  position: fixed;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
  opacity: 0.025;
  pointer-events: none;
  z-index: 9999;
}

import React from 'react'
import ReactDOM from 'react-dom/client'
import './index.css'

// Determine which page to render based on the current path
const path = window.location.pathname

const renderPage = async () => {
  let PageComponent: React.FC

  if (path.includes('learn')) {
    const { LearnPage } = await import('./pages/LearnPage')
    PageComponent = LearnPage
  } else if (path.includes('donate')) {
    const { DonatePage } = await import('./pages/DonatePage')
    PageComponent = DonatePage
  } else if (path.includes('tag-ai')) {
    const { TagAiPage } = await import('./pages/TagAiPage')
    PageComponent = TagAiPage
  } else if (path.includes('tag-web-scraping')) {
    const { TagScrapingPage } = await import('./pages/TagScrapingPage')
    PageComponent = TagScrapingPage
  } else {
    const { HomePage } = await import('./pages/HomePage')
    PageComponent = HomePage
  }

  const root = document.getElementById('app')
  if (root) {
    ReactDOM.createRoot(root).render(
      <React.StrictMode>
        <PageComponent />
      </React.StrictMode>
    )
  }
}

renderPage()

import React, { useState } from "react"
import { Header } from "@/components/Header"
import { Banner } from "@/components/Banner"
import { Footer } from "@/components/Footer"
import { ArticleCard } from "@/components/ArticleCard"
import { Button } from "@/components/ui/button"

const initialArticles = [
  {
    tag: "#AI",
    title: "Shadow AI Explained: Why Employees Are Using AI Behind Your Back",
    author: "Manish Shivanandhan",
    time: "15 hours ago",
  },
  {
    tag: "#web scraping",
    title: "Traditional Scraping vs AI Scraping: A Practical Guide for Developers and Data Teams",
    author: "Joel Olawanle",
    time: "16 hours ago",
  },
  {
    tag: "#Databases",
    title: "How Database Indexes Work – A Practical Guide with PostgreSQL Examples",
    author: "iyiola",
    time: "20 hours ago",
  },
  {
    tag: "#elasticsearch",
    title: "How to Streamline Search in Web Applications with Elasticsearch",
    author: "Oluwatobi",
    time: "21 hours ago",
  },
  {
    tag: "#data-engineering",
    title: "How to Build an Open Source Data Lake for Batch Ingestion",
    author: "Puneet Singh",
    time: "a day ago",
  },
]

const moreArticles = [
  {
    tag: "#AI",
    title: "The AI Governance Handbook: How to Build Responsible AI Systems That Actually Ship",
    author: "Rudrendu Paul",
    time: "3 days ago",
  },
  {
    tag: "#AI",
    title: "GPT-5.4 vs GLM-5: Is Open Source Finally Matching Proprietary AI?",
    author: "Oyedele Tioluwani",
    time: "4 days ago",
  },
  {
    tag: "#web scraping",
    title: "How to Turn Websites into LLM-Ready Data Using Firecrawl",
    author: "Manish Shivanandhan",
    time: "6 months ago",
  },
  {
    tag: "#Python",
    title: "How to Use Python to Build Your Own Web Scraper",
    author: "—",
    time: "2 years ago",
  },
  {
    tag: "#Databases",
    title: "SQL vs NoSQL: Choosing the Right Database for Your Application",
    author: "Sarah Chen",
    time: "5 days ago",
  },
]

export function HomePage() {
  const [articles, setArticles] = useState(initialArticles)
  const [loadedMore, setLoadedMore] = useState(false)

  const handleLoadMore = () => {
    setArticles((prev) => [...prev, ...moreArticles])
    setLoadedMore(true)
  }

  return (
    <div className="grain min-h-screen bg-[#fafaf9]">
      <Header />
      <Banner />

      <main className="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8">
        {/* Featured Article */}
        <section className="mb-12">
          <ArticleCard
            tag="#AI"
            title="Shadow AI Explained: Why Employees Are Using AI Behind Your Back"
            author="Manish Shivanandhan"
            time="15 hours ago"
            featured
          />
        </section>

        {/* Latest Tutorials */}
        <section>
          <div className="mb-6 flex items-center justify-between">
            <h2 className="text-2xl font-bold text-[#0a0a23]" style={{ fontFamily: 'var(--font-display)' }}>
              Latest Tutorials
            </h2>
          </div>

          <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {articles.map((article, index) => (
              <div
                key={`${article.title}-${index}`}
                className="animate-fade-in-up"
                style={{ animationDelay: `${index * 50}ms` }}
              >
                <ArticleCard
                  tag={article.tag}
                  title={article.title}
                  author={article.author}
                  time={article.time}
                />
              </div>
            ))}
          </div>

          {!loadedMore && (
            <div className="mt-10 flex justify-center">
              <Button
                onClick={handleLoadMore}
                className="h-11 rounded-md bg-[#0a0a23] px-8 text-sm font-semibold text-white transition-colors hover:bg-[#0a0a23]/90"
              >
                Load More Articles
              </Button>
            </div>
          )}
        </section>
      </main>

      <Footer />
    </div>
  )
}

